// Independent negative controls. No frozen source/report/oracle is edited.
#include <nlohmann/json.hpp>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
using J=nlohmann::json; namespace fs=std::filesystem;
void save(const fs::path&p,const J&j){if(fs::exists(p))throw std::runtime_error("fresh input required");std::ofstream f(p);f<<j.dump(2)<<'\n';if(!f)throw std::runtime_error("write");}
J dist(int n,double v){if(!n)return {{"n",0}};return {{"n",n},{"p50",v},{"p95",v},{"p99",v},{"max",v},{"jitter_p95_minus_p5",0}};}
J plan(int intent=1){return {{"event","own_accepted_plan"},{"epoch",1},{"generation",1},{"geometry",1},{"note",intent},{"intent",intent},{"revision",1},{"source_frame",1},{"evidence",100},{"valid_until",500},{"prefix_offset",0},{"basis","test_only"},{"steps",J::array({{{"phase",0},{"x",400},{"y",500},{"due",150}},{{"phase",2},{"x",400},{"y",500},{"due",250}}})}};}
J receipt(int phase,int intent=1){return {{"event","own_injection_receipt"},{"intent",intent},{"contact",0},{"phase",phase},{"x",400},{"y",500},{"source_frame",1},{"scheduled",phase==0?150:250},{"injection_start",phase==0?160:260},{"injection_return",phase==0?170:270},{"success",true},{"reason","synthetic_success"}};}
J release(bool unknown=false){return {{"event","release_receipt"},{"requested",J::array({0})},{"failed",J::array()},{"unknown",unknown?J::array({0}):J::array()},{"start",280},{"return",290}};}
J attempts(){J a=J::array();for(int i=0;i<2560;++i)a.push_back({{"attempt",i+1},{"capture",100+i*1000},{"published_ok",true},{"consumed",true},{"owned",true},{"published",120+i*1000},{"owner_complete",300+i*1000},{"journal_enqueue_complete",400+i*1000},{"observer_ns",100},{"hook_ns",50},{"owner_ns",50},{"writer_ok",true}});return a;}
J complete_events(){J a=J::array();for(int i=0;i<2560;++i)a.push_back({{"event","complete_current_chain"},{"frame",i+1},{"capture",100+i*1000}});return a;}
J report(){return {{"schema","pas.prelive-complete-chain-cost.v1"},{"mode","A"},{"scene","tap"},{"attempts",2560},{"requested",2560},{"warmup_attempts",256},{"cadence_ms",20},{"consumed",2560},{"owner_seen",2560},{"owner_seen_fraction",1},{"published",2560},{"pool_drops",0},{"unconsumed",0},{"consumer_skips",0},{"writer_ok",2560},{"writer_fault",false},{"writer_drops",0},{"journal_admission_failed",false},{"journal_records",2563},{"journal_admitted_bytes",1000000},{"injection_failed",0},{"own_down",1},{"own_move",0},{"own_up",1},{"receipt_count",2},{"release_calls",0},{"release_verified",true},{"safe",true},{"rss_peak_os",1024},{"capture_to_owner_ms",dist(2560,.0002)},{"capture_to_owner_journal_ms",dist(2560,.0003)},{"capture_to_publish_ms",dist(2560,.00002)},{"all_phase_lateness_ms",dist(2,.00001)},{"injection_ms",dist(2,.00001)},{"phase_lateness_ms",{{"down",dist(1,.00001)},{"move",dist(0,0)},{"up",dist(1,.00001)}}},{"evidence_to_injection_ms",{{"n",2},{"p50",.00011},{"p95",.000155},{"p99",.000159},{"max",.00016},{"jitter_p95_minus_p5",.00009}}},{"measurement",{{"attempts",2304},{"owner_seen",2304},{"owner_seen_fraction",1},{"observer_ms",dist(2304,.0001)},{"hook_ms",dist(2304,.00005)},{"owner_ms",dist(2304,.00005)},{"capture_to_owner_ms",dist(2304,.0002)}}}};}
void write_case(const fs::path&root,const std::string&name,J r,J ev,J at=attempts()){
 const auto p=root/(name+".json");r["journal_records"]=ev.size();save(p,r);save(p.string()+".attempts.json",at);std::ofstream f(p.string()+".journal.jsonl");for(const auto&e:ev)f<<e.dump()<<'\n';if(!f)throw std::runtime_error("write journal");save(root/(name+"-gate-input.json"),{{"path",p.string()}});
}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage output_root original_passing_tap_report");fs::path root=fs::absolute(argv[1]);if(fs::exists(root))throw std::runtime_error("fresh output root");fs::create_directories(root);
 J base=J::array({plan(),receipt(0),receipt(2)});for(const auto&e:complete_events())base.push_back(e);
 write_case(root,"control-valid",report(),base);
 {auto e=base;e[1]["x"]=999;e[1]["source_frame"]=999;e[1]["scheduled"]=999999;write_case(root,"receipt-plan-mismatch",report(),e);}
 {auto e=base;e.insert(e.begin()+1,plan(2));e[3]["intent"]=2;write_case(root,"cross-intent-up",report(),e);}
 {auto e=base;e.insert(e.begin()+3,receipt(0));e.insert(e.begin()+4,receipt(2));auto r=report();r["own_down"]=2;r["own_up"]=2;r["receipt_count"]=4;write_case(root,"completed-intent-rebirth",r,e);}
 {auto e=base;e.erase(e.begin()+2);e.insert(e.begin()+2,release(true));e.insert(e.begin()+3,release(false));auto r=report();r["own_up"]=0;r["receipt_count"]=1;r["release_calls"]=2;write_case(root,"unknown-release-overwritten",r,e);}
 {auto r=report();r["capture_to_owner_ms"]["n"]=777;r["capture_to_owner_ms"]["p99"]=99;r["capture_to_owner_ms"]["max"]=200;write_case(root,"fabricated-cost-distribution",r,base);}
 {auto a=attempts();a[0]["owner_complete"]=500000100;a[0]["journal_enqueue_complete"]=500000200;write_case(root,"500ms-raw-latency-green-summary",report(),base,a);}
 {auto r=report();r["attempts"]=123;write_case(root,"attempts-field-mismatch",r,base);}
 {auto e=base;for(auto&row:e)if(row.value("event","")=="own_injection_receipt"){row.erase("x");row.erase("y");}write_case(root,"legacy-no-coordinate-join",report(),e);}
 {const auto p=root/"pixel-incomplete.json";save(p,{{"schema","pas.prelive-current-pixels.v1"},{"frames",2},{"processed",1},{"own_down",0},{"own_move",0},{"own_up",0},{"release_verified",true},{"compute_ms",dist(1,1)}});std::ofstream rows(p.string()+".rows.jsonl");rows<<J{{"ordinal",1},{"window",0},{"source_frame",1},{"capture",100},{"pixels_ready",100},{"complete_ms",1}}.dump()<<'\n';std::ofstream(p.string()+".events.jsonl");}
 {auto e=base;auto cancellation=J{{"event","game_contact_cancelled"},{"intent_id",1},{"cancel_ns",250}};e.insert(e.begin()+2,cancellation);e[3]["scheduled"]=255;auto r=report();r["all_phase_lateness_ms"]={{"n",2},{"p50",.0000075},{"p95",.00000975},{"p99",.00000995},{"max",.00001},{"jitter_p95_minus_p5",.0000045}};r["phase_lateness_ms"]["up"]=dist(1,.000005);write_case(root,"control-cancellation-up",r,e);}
 {auto e=base;e[1]["success"]=false;e.erase(e.begin()+2);e.insert(e.begin()+2,release(false));auto r=report();r["own_up"]=0;r["receipt_count"]=1;r["release_calls"]=1;r["injection_failed"]=1;r["safe"]=false;r["all_phase_lateness_ms"]=dist(1,.00001);r["injection_ms"]=dist(1,.00001);r["phase_lateness_ms"]["up"]=dist(0,0);r["evidence_to_injection_ms"]=dist(1,.00006);write_case(root,"control-unknown-down-released",r,e);}
 {auto e=base;auto p=plan();p["revision"]=2;p["source_frame"]=2;p["evidence"]=1100;p["prefix_offset"]=1;p["steps"]=J::array({{{"phase",1},{"x",400},{"y",500},{"due",200}},{{"phase",2},{"x",400},{"y",500},{"due",1250}}});e[0]["steps"].insert(e[0]["steps"].begin()+1,J{{"phase",1},{"x",400},{"y",500},{"due",200}});auto move=receipt(0);move["phase"]=1;move["scheduled"]=200;move["injection_start"]=210;move["injection_return"]=220;e.insert(e.begin()+2,move);e.insert(e.begin()+3,p);e[4]["source_frame"]=2;e[4]["scheduled"]=1250;e[4]["injection_start"]=1260;e[4]["injection_return"]=1270;auto r=report();r["own_move"]=1;r["receipt_count"]=3;r["all_phase_lateness_ms"]=dist(3,.00001);r["injection_ms"]=dist(3,.00001);r["phase_lateness_ms"]["move"]=dist(1,.00001);r["evidence_to_injection_ms"]={{"n",3},{"p50",.00011},{"p95",.000155},{"p99",.000159},{"max",.00016},{"jitter_p95_minus_p5",.00009}};write_case(root,"control-compacted-prefix",r,e);e[4]["scheduled"]=1251;write_case(root,"compacted-prefix-step-mismatch",r,e);}
 {auto e=base;auto p=plan(2);p["note"]=1;e.insert(e.begin()+3,p);e.insert(e.begin()+4,receipt(0,2));e.insert(e.begin()+5,receipt(2,2));auto r=report();r["own_down"]=2;r["own_up"]=2;r["receipt_count"]=4;write_case(root,"same-note-new-intent-rebirth",r,e);}
 {auto r=report();r["provenance"]={{"run_id","synthetic-provenance-control"},{"process",{{"pid",123},{"creation_filetime",321},{"run_start_ns",1}}}};auto e=base;e.insert(e.begin(),J{{"event","current_chain_provenance"},{"provenance",r["provenance"]}});write_case(root,"control-provenance-join",r,e);auto mismatch=e;mismatch[0]["provenance"]["run_id"]="different-run";write_case(root,"provenance-report-event-mismatch",r,mismatch);e.insert(e.begin(),e[0]);write_case(root,"provenance-duplicate-event",r,e);write_case(root,"provenance-event-missing",r,base);}
 {auto e=base;e[0]["source_frame"]=257;e[0]["evidence"]=256100;e[0]["valid_until"]=256500;for(auto&step:e[0]["steps"])step["due"]=step["due"].get<int>()+256000;for(int i:{1,2}){e[i]["source_frame"]=257;for(const auto&field:{"scheduled","injection_start","injection_return"})e[i][field]=e[i][field].get<int>()+256000;}write_case(root,"control-measurement-actions",report(),e);}
 {auto a=attempts();a[0]["owner_complete"]=std::numeric_limits<std::int64_t>::min();a[0]["journal_enqueue_complete"]=std::numeric_limits<std::int64_t>::max();write_case(root,"malformed-int64-overflow",report(),base,a);}
 J repeated=J::array();for(const auto& load:{"tap","hold","dense"})for(int i=0;i<4;++i)repeated.push_back({{"scene",load},{"path",fs::absolute(argv[2]).string()},{"sha256",std::string(64,'0')}});
 save(root/"repeated-tap-aa-input.json",{{"runs",repeated},{"normal_stopped",false}});
 std::cout<<root<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
